import{_ as a,o as t,c as r,a2 as n}from"./chunks/framework.D9E58p8B.js";const m=JSON.parse(`{"title":"Regarder l'écran","description":"","frontmatter":{"title":"Regarder l'écran"},"headers":[],"relativePath":"agent/regarder.md","filePath":"agent/regarder.md"}`),o={name:"agent/regarder.md"};function i(l,e,d,s,u,c){return t(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="regarder-l-ecran" tabindex="-1">Regarder l&#39;écran <a class="header-anchor" href="#regarder-l-ecran" aria-label="Permalink to &quot;Regarder l&#39;écran&quot;">​</a></h1><p>C&#39;est le point de départ de presque toute tâche : l&#39;agent voit ce que vous voyez.</p><h2 id="ce-que-vous-demandez" tabindex="-1">Ce que vous demandez <a class="header-anchor" href="#ce-que-vous-demandez" aria-label="Permalink to &quot;Ce que vous demandez&quot;">​</a></h2><blockquote><p>« Regarde mon écran et dis-moi quelle fenêtre est au premier plan. »</p><p>« Trouve le bouton Enregistrer à l&#39;écran. »</p></blockquote><h2 id="ce-que-fait-l-agent" tabindex="-1">Ce que fait l&#39;agent <a class="header-anchor" href="#ce-que-fait-l-agent" aria-label="Permalink to &quot;Ce que fait l&#39;agent&quot;">​</a></h2><ol><li><a href="/Daimon/reference/vue.html#vue-displays"><code>vue_displays</code></a> liste les écrans, avec leur indice. Avec deux écrans, l&#39;agent sait ainsi lequel regarder.</li><li><a href="/Daimon/reference/vue.html#vue-snapshot"><code>vue_snapshot</code></a> capture un écran. Il renvoie un contrat de coordonnées (<code>coord_space</code>) puis l&#39;image. Par défaut l&#39;image est réduite à 720 pixels de large : l&#39;agent en demande davantage pour du détail fin, ou limite la capture à une <code>region</code>.</li><li><a href="/Daimon/reference/vue.html#vue-find"><code>vue_find</code></a> localise un libellé <strong>visible</strong> par OCR sur l&#39;appareil et rend des coordonnées cliquables. Il sert surtout quand <a href="/Daimon/agent/lire-interface.html">Touché</a> ne voit rien.</li><li><a href="/Daimon/reference/vue.html#vue-resolve"><code>vue_resolve</code></a> convertit un pixel de l&#39;image en point global, et inversement, sans capturer : l&#39;agent n&#39;a pas à calculer décalage et échelle.</li></ol><h2 id="ce-que-vous-obtenez" tabindex="-1">Ce que vous obtenez <a class="header-anchor" href="#ce-que-vous-obtenez" aria-label="Permalink to &quot;Ce que vous obtenez&quot;">​</a></h2><p>Une description, une position, ou un point cliquable. <strong>Daimon n&#39;interprète pas l&#39;image</strong> : c&#39;est votre agent qui la regarde et qui décide.</p><h2 id="ce-que-daimon-masque" tabindex="-1">Ce que Daimon masque <a class="header-anchor" href="#ce-que-daimon-masque" aria-label="Permalink to &quot;Ce que Daimon masque&quot;">​</a></h2><p>Les fenêtres des applications que vous protégez, les zones déclarées et les champs secrets ne sont jamais refusés : ils sont <strong>censurés</strong>, remplacés par un aplat violet opaque <code>#3A2A5C</code>. Votre agent sait qu&#39;une zone de cette couleur est du contenu masqué, pas un écran vide. L&#39;OCR lit l&#39;image censurée : il ne renvoie aucun mot qui touche une zone censurée. Voir <a href="/Daimon/guide/confidentialite.html">Confidentialité</a>.</p><h2 id="si-l-appel-est-refuse" tabindex="-1">Si l&#39;appel est refusé <a class="header-anchor" href="#si-l-appel-est-refuse" aria-label="Permalink to &quot;Si l&#39;appel est refusé&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Code</th><th>Ce que l&#39;agent doit faire</th></tr></thead><tbody><tr><td><code>permission_denied</code></td><td>L&#39;autorisation <strong>Enregistrement de l&#39;écran</strong> manque : <a href="/Daimon/guide/autorisations.html">Autorisations</a></td></tr><tr><td><code>invalid_arguments</code></td><td>Corriger l&#39;argument</td></tr><tr><td><code>index_out_of_range</code></td><td>L&#39;écran demandé n&#39;existe pas : relire <code>vue_displays</code></td></tr><tr><td><code>capture_failed</code></td><td>Réessayer, puis appeler <code>daimon_doctor</code></td></tr><tr><td><code>exclusions_unreadable</code></td><td>Votre fichier d&#39;exclusions est cassé : le message nomme le fichier et la ligne</td></tr></tbody></table><p>Détail complet : <a href="/Daimon/reference/vue.html">Vue</a>.</p><p>Suite : <a href="/Daimon/agent/lire-interface.html">Lire une interface</a>, ou <a href="/Daimon/agent/agir.html">Agir</a>.</p>',14)])])}const h=a(o,[["render",i]]);export{m as __pageData,h as default};
